SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, act.standard_type, act.standard_value, act.standard_units FROM molecule_dictionary md JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_structures cs ON md.molregno = cs.molregno WHERE td.organism = 'Homo sapiens' AND td.target_type = 'SINGLE PROTEIN' AND act.standard_type = 'Ki' AND act.standard_value < 100 ORDER BY md.chembl_id, cs.canonical_smiles, act.standard_type, act.standard_value, act.standard_units LIMIT 500
